mapper.select:
SELECT packageId, packageName, packageDescription, packageGrade, packagePrice, packageStatus, viewCount, createdAt, updatedAt, thumbnailUrl FROM ( SELECT P.PACKAGE_ID AS packageId, P.PACKAGE_NAME AS packageName, P.PACKAGE_DESCRIPTION AS packageDescription, P.PACKAGE_GRADE AS packageGrade, P.PACKAGE_PRICE AS packagePrice, P.PACKAGE_STATUS AS packageStatus, P.VIEW_COUNT AS viewCount, P.CREATED_AT AS createdAt, P.UPDATED_AT AS updatedAt, ( SELECT PI.IMAGE_URL FROM PACKAGE_IMAGE PI WHERE PI.PACKAGE_ID = P.PACKAGE_ID AND PI.IMAGE_TYPE = 'THUMBNAIL' ) AS thumbnailUrl, ROW_NUMBER() OVER ( PARTITION BY P.PACKAGE_GRADE ORDER BY P.CREATED_AT DESC ) AS rowNum FROM PACKAGE P
JOIN PACKAGE_TARGET PT ON P.PACKAGE_ID = PT.PACKAGE_ID
JOIN PACKAGE_PURPOSE PP ON P.PACKAGE_ID = PP.PACKAGE_ID
WHERE P.PACKAGE_STATUS = 'SELLING'
AND PT.TARGET_TYPE = #{targetType}
AND PP.PURPOSE_TYPE = #{purposeType}
) AS packageList WHERE rowNum <= 5 ORDER BY packageGrade, rowNum
